import{z as s,x as d,o as t,c as p,q as E,j as r,D as e,d as i,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"二进制协议 OUCH / SBE","description":"","frontmatter":{"title":"二进制协议 OUCH / SBE","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/binary-protocols-ouch-sbe.md","filePath":"quant/binary-protocols-ouch-sbe.md","lastUpdated":1791413859000}'),B={name:"quant/binary-protocols-ouch-sbe.md"};function A(c,a,C,h,u,S){const o=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="二进制协议-ouch-sbe" tabindex="-1">二进制协议 OUCH / SBE <a class="header-anchor" href="#二进制协议-ouch-sbe" aria-label="Permalink to &quot;二进制协议 OUCH / SBE&quot;">​</a></h1><div class="epigraph"><p>当 FIX 的文本标签成为延迟预算里可见的一截，交易所把同一生命周期收成定长或模板化的二进制帧：字段位置即契约，解析不再扫描等号。</p><footer>—— NASDAQ OUCH 规格；CME Group, Simple Binary Encoding (SBE)；对照 FIX Trading Community 对 FAST/SBE 的说明</footer></div><p><a href="/quant/fix-protocol">上一课</a>把机构订单语言停在 FIX。本课的缺口是<strong>交易所本地端口</strong>：OUCH（纳斯达克一类订单入口）、ITCH（行情）、CME MDP 的 SBE 模板。策略意图不变，编码与会话假设变了。后课快照与增量建立在这些帧上。不把二进制当成「更快的 FIX 全文翻译」——字段子集通常更小，语义更贴撮合核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FIX 为人类与多对手方互操作优化：标签可扩展、版本可混。本地端口为核的入队优化：定长头、整数价格（tick 的整数倍）、会话内序号、尽量零拷贝。OUCH 的新订单、改单、撤单、被拒、已接受、已成交是紧凑结构体；价格与数量的单位在规格里写死。问题是：同一 ClOrdID 生命周期在 FIX 柜台与 OUCH 端口上如何对齐。经经纪商转报时，你看见 FIX，经纪商对交易所可能是 OUCH；你的延迟预算必须声明测的是哪一跳。</p><p>SBE 把「模板 ID + 版本 + 定长块 + 可选变长」做成可代码生成的编解码。CME MDP 3.0 用它推增量行情与统计。模板升级不兼容时，旧解码器会静默读错字段——这比 FIX 漏标签更危险，因为没有标签名可对。研究管道必须把模板版本写入数据血缘，不能只存「CME 二进制 dump」。</p><h3 id="整数价格与字节序是契约" tabindex="-1">整数价格与字节序是契约 <a class="header-anchor" href="#整数价格与字节序是契约" aria-label="Permalink to &quot;整数价格与字节序是契约&quot;">​</a></h3><p>二进制价格几乎总是 <code>int64</code> 乘以规格中的 <code>PriceRatio</code> 或最小变动。把 IEEE 浮点打进端口，或者在本机用 double 往返后再比较 tick，会在边界价上错一档。字节序（SBE 默认 little endian）与对齐填充必须按规格，不能按本机 C 结构体布局臆造。OUCH 的用户自定义字段更少，防自成交、时效、展示量以枚举存在；A 股本地二进制接口则把涨跌幅、股东账户、订单类型编码进私有头——同一「二进制」不可混用解码器。</p><p><span class="marginnote">数字实例：规格若定 \\(PriceRatio = 0.0001\\)，价格 123.45 就存成整数 1,234,500；若先把 123.45 存成 double 再乘回去，二进制浮点可能得到 123.4499999…，比较 tick 时恰好差一档，订单会被交易所整单拒绝。</span></p><p><span class="marginnote">ITCH 是行情，OUCH 是订单入口，二者订单号空间相关但通道分离。用 ITCH 重建的簿去核对 OUCH 成交，必须对齐引擎序号或订单号，而不是对齐「差不多同一毫秒」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解码层只做规格映射：帧 → 内部事件（与上一课内部订单对象同构）。禁止在解码器里做策略。代码生成（SBE XML 模板 → 编解码）优于手写偏移，但生成物要进版本控制，模板变更必须出差异报告。会话层仍有序号与心跳；二进制不免除重连重放。测试用交易所认证工具或仿真器对拍，字段级黄金样本留在仓库。</p><p>延迟测量分段：网卡时间戳、用户态收包、解码完成、风控完成、发送完成。把「OUCH 比 FIX 快」写成一个数字是无意义的，除非固定同一主机、同一核、同一报文意图。FAST（FIX Adapted for Streaming）曾用于行情压缩，与 SBE 是不同代的二进制思路：FAST 偏压缩，SBE 偏定长可预测。选择由交易所决定，研究只声明。</p>',13)),(t(),r(l,null,{default:e(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E7%BD%91%E5%8D%A1%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%20--%3E%20T1%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E6%94%B6%E5%8C%85%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E8%A7%A3%E7%A0%81%E5%AE%8C%E6%88%90%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E9%A3%8E%E6%8E%A7%E5%AE%8C%E6%88%90%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E5%8F%91%E9%80%81%E5%AE%8C%E6%88%90%22%5D%0A%20%20T4%20--%3E%20REP%5B%22%E5%88%86%E6%AE%B5%E6%8A%A5%E5%91%8A%20%E6%AF%8F%E8%B7%B3%E5%8D%95%E7%8B%AC%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">术语翻译：「零拷贝」就是数据从网卡到你的缓冲区全程不做多余的内存复制——每多拷一次，就多一次内存带宽开销和几微秒延迟。对连微秒都要斤斤计较的端口来说，拷贝次数本身就是被优化的对象。</span></p><h3 id="与-fix-网关并存时的身份映射" tabindex="-1">与 FIX 网关并存时的身份映射 <a class="header-anchor" href="#与-fix-网关并存时的身份映射" aria-label="Permalink to &quot;与 FIX 网关并存时的身份映射&quot;">​</a></h3><p>许多机构同时跑 FIX 到 EMS、二进制到托管主机。内部必须有一张表：策略单号 → FIX ClOrdID → 交易所 token。事故回放按这张表拼接，而不是按时间窗口模糊匹配。部分成交在二进制里可能是一条 execution 帧加剩余量；不要假设一定有 FIX 那种多次 35=8 文本。</p><p><span class="marginnote">为什么不能按时间窗口模糊匹配：同一策略一毫秒内可能发出几十笔单，按「差不多同一时刻」拼帧，部分成交与撤单会拼到别的单头上；只有单号映射表能把事故回放拼成因果链，而不是巧合链。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定长帧把解析从「扫描」变成「偏移」，抖动下降，这才是对时间优先的贡献：入核前的 CPU 时间更可预测。它不改变核内 FIFO。若应用在解码后仍做内存分配、日志 flush、锁竞争，二进制的优势会被吃掉——后课内核旁路处理这一段。行情 SBE 增量与订单 OUCH 仍可能不同通道、不同网卡，时钟校准见后课时钟课。</p><p>模板化编码使「向前兼容」变成显式版本协商。忽略版本、强行解码，是状态机腐败的常见原因，症状与丢包相似：簿对不上、成交价不在 BBO。处理同上一课：停用，冷启动。</p>',7)),(t(),r(l,null,{default:e(()=>[n(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Intent%5B%22%E5%90%8C%E4%B8%80%E7%BB%8F%E6%B5%8E%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20FIX%5B%22FIX%20%E6%A0%87%E7%AD%BE%E4%BC%9A%E8%AF%9D%22%5D%0A%20%20Intent%20--%3E%20Bin%5B%22OUCH%20%2F%20SBE%20%E6%9C%AC%E5%9C%B0%E5%B8%A7%22%5D%0A%20%20FIX%20--%3E%20EMS%5B%22%E7%BB%8F%E7%BA%AA%E5%95%86%E8%BD%AC%E6%8A%A5%22%5D%0A%20%20Bin%20--%3E%20Gate%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E6%9C%AC%E5%9C%B0%E7%BD%91%E5%85%B3%22%5D%0A%20%20EMS%20--%3E%20Gate%0A%20%20Gate%20--%3E%20Core%5B%22%E6%92%AE%E5%90%88%E6%A0%B8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供利用二进制端口插队、抢跑或构造畸形帧的方法。畸形帧属于对交易所系统的攻击面，研究只需把规格校验当硬拒。私有协议无公开规格时，以会员文档为准，不要用纳斯达克 OUCH 去猜上交所二进制。</p><p>加密 websocket JSON、REST 下单延迟特征不同，不要标成 SBE。ISO 20022 是清算报文，不走撮合端口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OUCH/SBE 把订单与行情收成定长或模板帧，解析可预测，字段子集更贴核。</li><li>价格用整数 tick；模板版本是血缘字段；与 FIX 并存时要显式映射单号。</li><li>二进制不改变撮合优先规则，只改变入核前的抖动。</li><li>出处：NASDAQ OUCH；CME SBE / MDP 3.0 规格；FIX Trading Community。</li></ul>',5))])}const T=s(B,[["render",A]]);export{_ as __pageData,T as default};
